<template><section><div class="toolbar"><button class="secondary-button" @click="cy?.fit(undefined,55)">전체 보기</button><button class="secondary-button" @click="layout">자동 배치</button><button class="secondary-button" @click="cy?.zoom(cy.zoom()*1.2)" aria-label="확대">＋</button><button class="secondary-button" @click="cy?.zoom(cy.zoom()/1.2)" aria-label="축소">−</button><span class="muted">드래그로 이동 · 노드를 눌러 프로필 열기</span></div><div ref="container" class="relationship-canvas" role="img" aria-label="승인된 캐릭터 관계도"></div><div v-if="selected" class="card relation-description"><h3>{{selected.label}}</h3><p class="prose">{{selected.description || '등록된 설명이 없습니다.'}}</p></div></section></template>
<script setup>
import {ref,watch,onMounted,onBeforeUnmount} from 'vue';import {useRouter} from 'vue-router';import cytoscape from 'cytoscape';import {graphElements} from './domain.mjs';
const props=defineProps({characters:Array,relationships:Array,faction:String,kind:String,focus:String});const router=useRouter();const container=ref();const selected=ref(null);let cy;
function layout(){cy?.layout({name:'cose',animate:false,nodeRepulsion:()=>12000,idealEdgeLength:()=>170,padding:55}).run();}
function draw(){if(!cy)return;cy.elements().remove();cy.add(graphElements(props.characters,props.relationships,props.faction,props.kind));layout();highlight();}
function highlight(){if(!cy)return;cy.elements().removeClass('faded');if(props.focus){const node=cy.getElementById(props.focus);if(node.length)cy.elements().difference(node.closedNeighborhood()).addClass('faded');}}
onMounted(()=>{cy=cytoscape({container:container.value,minZoom:.15,maxZoom:3,style:[{selector:'node',style:{label:'data(label)',width:72,height:72,'background-color':'#627f9b','border-width':3,'border-color':'#b6c9dc',color:'#574941','text-valign':'bottom','text-margin-y':12,'font-family':'Batang','font-size':14,'text-background-color':'#fffdfb','text-background-opacity':.9,'text-background-padding':4}},{selector:'node[image != ""]',style:{'background-image':'data(image)','background-fit':'cover'}},{selector:'node[faction = "templar"]',style:{'background-color':'#9d5c61','border-color':'#d5a5a8'}},{selector:'edge',style:{label:'data(label)',width:2,'line-color':'#b49a89','curve-style':'bezier','text-rotation':'autorotate','text-background-color':'#f6f3ef','text-background-opacity':1,'text-background-padding':5,'font-size':11,color:'#786253'}},{selector:'edge[?directed]',style:{'target-arrow-shape':'triangle','target-arrow-color':'#b49a89'}},{selector:'.faded',style:{opacity:.15}}]});cy.on('tap','node',e=>router.push('/characters/'+e.target.id()));cy.on('tap','edge',e=>selected.value=e.target.data());draw();});
watch(()=>[props.characters,props.relationships,props.faction,props.kind],draw,{deep:true});watch(()=>props.focus,highlight);onBeforeUnmount(()=>cy?.destroy());
</script>
